UPDATE demand_matches
SET confirm_status = 'rejected',
    confirmed_by   = #{rejectedBy},
    confirmed_at   = NOW(6),
    updated_at     = NOW(6)
WHERE demand_id = #{demandId}
  AND is_delete = 0
  AND confirm_status != 'confirmed'
  AND (
      CAST(id AS CHAR) = #{resultId}
      OR achievement_doc_id = #{resultId}
  )
